//! A5 Go-escape check-site (`HYB-E3013`) — non-mutating, value-isolated, and `managed` method values stay accepted.
use hy_check::{check_file, Verdict};
use hy_syntax::parse_file;

fn assert_clean(src: &str) {
    let r = check_file(&parse_file("t.hy", src).expect("snippet parses"));
    assert_eq!(r.verdict, Verdict::Accept, "unexpected {:?}: {:?} for:\n{src}", r.verdict, r.diagnostics);
}
const PRE: &str = "import \"net/http\"\nimport \"time\"\ntype cb_fn = fn()\nstruct stats { n int }\nstruct clean { n int }\nstruct slice_holder { xs []int }\nstruct mixed {\n    m map[string]int\n    n int\n    xs [4]int\n}\nstruct cb_box {\n    r fn()\n    w fn()\n}\nstruct outer_box { bx cb_box }\nfn _use_pkgs() {\n    _ = time.second\n    http.handle_func(\"/k\", fn() {})\n}\nfn noop() {}\nfn bump(s *stats) { s.n++ }\nfn run_local(f fn()) { f() }\nfn run_box_r(bx cb_box) { bx.r() }\nfn ignore_cb(f fn()) { _ = f }\nfn (s *stats) incr() { s.n++ }\nfn (s *stats) report() { _ = s.n }\nfn (s *stats) noop() {}\nfn (s stats) scratch() {\n    s.n = 1\n    _ = s.n\n}\nfn (c *clean) incr() { _ = c.n }\nfn (h slice_holder) set() { h.xs[0] = 7 }\nfn (x mixed) touch_local() {\n    x.n = 1\n    x.xs[0] = 2\n    _ = x.n\n}\nfn make_cb(s *stats) fn() { return s.incr }\nfn make_copy(s stats) fn() { return s.incr }\nfn make_fresh() fn() {\n    s := stats{n: 0}\n    return s.incr\n}\nfn invoke_local_only(p *stats) {\n    _ = p\n    if true {\n        p := stats{n: 1}\n        arr := []fn(){p.incr}\n        arr[0]()\n    }\n}\nfn passthru_cb(f fn()) fn() { return f }\nfn make_box(s *stats) cb_box { return cb_box{r: s.report, w: s.incr} }\nfn pair_mut_first_clean_second(s *stats) (cb_fn, cb_fn) { return s.incr, s.report }";

#[test]
fn read_only_value_receiver_disambiguated_tuple_and_overwritten_accept() {
    assert_clean("struct stats { n int }\nfn run(f fn()) { f() }\nfn (s *stats) incr() { s.n++ }\nfn main() {\n    s := stats{n: 0}\n    run(s.incr)\n    _ = s\n}\n");
    for body in [
        "s := stats{n: 0}\nhttp.handle_func(\"/a\", s.report)\n_ = s", "s := stats{n: 0}\np := &s\nhttp.handle_func(\"/a\", p.report)", "s := stats{n: 0}\nhttp.handle_func(\"/a\", s.scratch)\n_ = s", "s := stats{n: 0}\np := &s\nhttp.handle_func(\"/a\", p.scratch)", "mx := mixed{m: map[string]int{}, n: 0, xs: [4]int{0, 0, 0, 0}}\nhttp.handle_func(\"/a\", mx.touch_local)\n_ = mx", "x := 1\nhttp.handle_func(\"/a\", (&stats{n: x}).incr)", "c := clean{n: 0}\nhttp.handle_func(\"/a\", c.incr)\n_ = c", "s := stats{n: 0}\nhttp.handle_func(\"/a\", make_copy(s))\n_ = s", "s := stats{n: 0}\ncb := s.incr\ncb = s.report\nhttp.handle_func(\"/a\", cb)\n_ = s", "s := stats{n: 0}\ncb := s.incr\nif s.n == 0 { cb = s.report } else { cb = s.noop }\nhttp.handle_func(\"/a\", cb)\n_ = s", "s := stats{n: 0}\ncb := s.incr\nif s.n == 0 {\ncb := s.report\nhttp.handle_func(\"/a\", cb)\n}\n_ = cb\n_ = s", "s := stats{n: 0}\ncbs := []fn(){s.report, s.incr}\nhttp.handle_func(\"/a\", cbs[0])\n_ = s",
        "s := stats{n: 0}\nmp := map[string]fn(){\"r\": s.report, \"w\": s.incr}\nhttp.handle_func(\"/a\", mp[\"r\"])\n_ = s", "s := stats{n: 0}\nbx := cb_box{r: s.report, w: s.incr}\nhttp.handle_func(\"/a\", bx.r)\n_ = s", "s := stats{n: 0}\n_, cb := pair_mut_first_clean_second(&s)\n_ = time.after_func(0, cb)", "if false {\nx := stats{n: 0}\n_ = x\n}\nx := clean{n: 0}\ncb := x.incr\n_ = time.after_func(0, cb)\n_ = x", "s := stats{n: 0}\n_ = time.after_func(0, passthru_cb(s.report))\n_ = s", "s := stats{n: 0}\nbx := make_box(&s)\n_ = time.after_func(0, bx.r)", "s := stats{n: 0}\nob := outer_box{bx: cb_box{r: s.report, w: s.incr}}\n_ = time.after_func(0, ob.bx.r)\n_ = s", "s := stats{n: 0}\nxs := []cb_box{cb_box{r: s.report, w: s.incr}}\n_ = time.after_func(0, xs[0].r)\n_ = s", "_ = time.after_func(0, fn() {\nls := stats{n: 0}\nf := ls.incr\nf()\nls.incr()\nbump(&ls)\n})", "s := stats{n: 0}\n_ = time.after_func(0, fn() { s.scratch() })\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\nrun_local(s.report)\nignore_cb(s.incr)\n})\n_ = s", "s := stats{n: 0}\n_ = time.after_func(0, fn() {\ns := stats{n: 1}\nf := s.incr\nf()\n})\n_ = s",
        "s := stats{n: 0}\ncb := s.report\nset_it := fn() {\ncb := s.incr\n_ = cb\n}\nset_it()\n_ = time.after_func(0, cb)\n_ = s", "s := stats{n: 0}\ncb := s.report\nrun := fn() { _ = time.after_func(0, cb) }\nif s.n == 0 {\ncb := s.incr\n_ = cb\n}\ncb = s.noop\nrun()\n_ = s", "s := stats{n: 0}\n_ = s\n_ = time.after_func(0, fn() {\ns := stats{n: 1}\ninner := fn() {\nf := s.incr\ns := stats{n: 2}\n_ = s\nf()\n}\ninner()\n})", "s := stats{n: 0}\n_ = s\n_ = time.after_func(0, fn() {\ns := stats{n: 1}\nf := make_cb(&s)\nf()\n})", "s := stats{n: 0}\n_ = s\n_ = time.after_func(0, fn() {\ns := stats{n: 1}\ng := fn() { s.n = 2 }\ng()\n})", "s2 := stats{n: 0}\n_ = s2\n_ = time.after_func(0, fn() {\nvar f fn() = noop\nif true {\ns2 := stats{n: 1}\nf = s2.incr\n}\nf()\n})", "_ = time.after_func(0, fn() {\nf := make_fresh()\nf()\n})", "s := stats{n: 0}\n_ = time.after_func(0, fn() { invoke_local_only(&s) })", "shared := []int{1, 2}\n_ = shared\nmk := fn() fn() {\nxs := []int{1}\nsh := slice_holder{xs: xs}\nreturn sh.set\n}\n_ = time.after_func(0, mk())", "s2 := stats{n: 0}\n_ = s2\n_ = time.after_func(0, fn() {\nvar f fn() = noop\nif true {\ns2 := stats{n: 1}\nf = fn() { s2.n = s2.n + 1 }\n}\nf()\n})", "s2 := stats{n: 0}\n_ = s2\n_ = time.after_func(0, fn() {\nls := stats{n: 1}\np := &ls\nif s2.n == 0 { p = &s2 }\np = &ls\np.n = 99\n})", "s := stats{n: 0}\n_ = s\n_ = time.after_func(0, fn() { run_box_r(cb_box{r: s.report, w: s.incr}) })", "s2 := stats{n: 0}\n_ = s2\n_ = time.after_func(0, fn() {\nls := stats{n: 1}\np := &ls\ng := fn() { p.n = 99 }\ng()\np = &s2\n_ = p\n})",
    ] { assert_clean(&format!("{PRE}\nfn main() {{\n{body}\n}}\n")); }
}
#[test]
fn managed_interop_escape_hatch_accepts_direct_nested_and_closure() {
    for body in [
        "s := stats{n: 0}\nmanaged(\"foreign sync\", \"interop\", \"#1\") { http.handle_func(\"/a\", s.incr) }\n_ = s", "s := stats{n: 0}\nmanaged(\"foreign sync\", \"interop\", \"#1\") {\nif s.n == 0 { http.handle_func(\"/a\", s.incr) }\n}\n_ = s", "s := stats{n: 0}\nmanaged(\"foreign sync\", \"interop\", \"#1\") {\nf := fn() { http.handle_func(\"/a\", s.incr) }\nf()\n}\n_ = s",
    ] { assert_clean(&format!("{PRE}\nfn main() {{\n{body}\n}}\n")); }
}
